/* Scripted onboarding preview. No OAuth, mailbox access or purchase occurs. */
const onboardingScreens=['Welcome','Connect inbox','Inbox permission','Discovering','Your subscriptions','Save your finds','Ready to go','Scan · no results','Scan · interrupted'];
const ob={selected:new Set([0,1,2]),timers:[],scan:0};
const obItems=[['Netflix','N','15.99','USD','27 Oct','Entertainment','2026-10-27'],['Spotify','S','11.99','USD','31 Oct','Music','2026-10-31',{trial:true,start:'2026-10-24',trialDays:7,autoRenew:true,trialEndSource:'exact'}],['iCloud+','☁','2.99','USD','30 Oct','Storage','2026-10-30']];
// Fixed sample date keeps the fictional receipt timeline reproducible.
function obUpcoming(){
 const today=Date.UTC(2026,9,26),day=86400000;
 const selected=obItems.filter((item,i)=>ob.selected.has(i));
 const upcoming=selected.filter(item=>item[6]&&Date.parse(item[6])>=today).sort((a,b)=>Date.parse(a[6])-Date.parse(b[6]));
 const week=upcoming.filter(item=>Date.parse(item[6])<=today+7*day);
 const totals=week.reduce((sum,item)=>{if(!item[7]?.trial||item[7]?.autoRenew!==false)sum[item[3]]=(sum[item[3]]||0)+Number(item[2]);return sum;},{});
 return `<section class="ob-renewal-line" aria-label="Upcoming renewals"><span><strong>${week.length} ${week.length===1?'upcoming event':'upcoming events'}</strong> in the next 7 days</span><span class="ob-renewal-amount">${Object.entries(totals).map(([currency,value])=>`${escape(currency)} ${value.toFixed(2)}`).join(' · ')||'—'}</span></section>`;
}
function obTop(n,back='Welcome'){return `<div class="ob-top">${current==='Welcome'?'<span class="ob-back"></span>':btn('‹',back,'ob-back')}<span>RENEWLESS</span><img src="assets/renewless-mark.svg" alt=""></div><div class="ob-steps" aria-label="Step ${n} of 5">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'done':''}"></i>`).join('')}</div>`;}
function obTitle(tag,title,copy){return `<div class="ob-intro"><p class="eyebrow">${tag}</p><h2>${title}</h2><p>${copy}</p></div>`;}
function obScene(){return `<div class="ob-scene" aria-label="An email receipt becomes an organized subscription"><div class="ob-orbit"></div><div class="ob-receipt"><span>✉ &nbsp; YOUR INBOX</span><strong>Your monthly receipt</strong><i></i><i></i><b>$15.99</b></div><div class="ob-found"><span class="ob-service">${platformLogo('Netflix')}</span><div><strong>Netflix</strong><small>Monthly · renews Oct 27</small></div><b>$15.99</b></div><div class="ob-pill">✓ &nbsp; Renewal found</div><img class="ob-loop" src="assets/loop-mascot.svg" alt="Loop"></div>`;}
function onboarding(){
 let body='';
 if(current==='Welcome')body=obTop(1)+obScene()+obTitle('LESS GUESSWORK. MORE CONTROL.','Know what renews.<br><em>Before it does.</em>','Find subscriptions in your Gmail, understand their cost, and stay ahead of renewals.')+`<div class="ob-benefits"><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg><span class="ob-benefit-label">Find</span></span><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg><span class="ob-benefit-label">Track</span></span><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4"/></svg><span class="ob-benefit-label">Remember</span></span></div><div class="ob-bottom">${btn('Find my subscriptions →','Connect inbox')}${btn('Already have an account? Log in','Login','link')}</div>`;
 if(current==='Connect inbox')body=obTop(2)+`<div class="ob-connect-art" role="img" aria-label="Connect Gmail to Renewless"><div class="ob-connection-brand"><span class="ob-connection-tile">${platformLogo('Gmail')}</span><span class="ob-connection-label">Gmail</span></div><svg class="ob-connection-arrow" viewBox="0 0 48 24" aria-hidden="true"><path d="M4 12h38m-7-7 7 7-7 7"/></svg><div class="ob-connection-brand"><span class="ob-connection-tile"><img src="assets/renewless-mark.svg" alt=""></span><span class="ob-connection-label">Renewless</span></div></div>`+obTitle('LET YOUR INBOX DO THE WORK','Less typing.<br><em>More discovering.</em>','Find recurring receipts and renewal emails from the last 12 months.')+`<div class="ob-trust">${fr('Read-only access','No sending or deleting')}${fr('You stay in control','Review before saving')}${fr('Gmail scans & updates','Included at no cost')}</div>${infoTooltip({"id": "email-processing-info", "label": "How your email is processed", "paragraphs": ["Google grants read access to your mailbox. Renewless filters relevant receipts and renewal emails, then uses AI to extract subscription details.", "You can disconnect your inbox. Your permission is required before processing."], "className": "ob-email-info"})}<div class="ob-bottom">${btn('Connect Gmail & scan','Inbox permission')}${btn('I’ll add subscriptions manually','Sign up','link')}</div>`;
 if(current==='Inbox permission')body=obTop(2,'Connect inbox')+`<div class="ob-symbol">${socialIcon('Google')}</div>`+obTitle('CONNECT YOUR INBOX','Your inbox.<br><em>Your permission.</em>','Choose your Google account and allow read-only access to find your subscriptions.')+panel('<strong>alex@example.com</strong><p class="muted">Read-only Gmail access to find receipts and renewals. AI extraction is used for relevant messages.</p>')+`<div class="ob-bottom">${btn('Continue with Google →','Discovering')}${btn('Not now','Connect inbox','secondary')}</div>`;
 if(current==='Discovering')body=obTop(3,'Connect inbox')+`<div class="ob-radar ob-discovery-art ${ob.scan===3?'is-complete':''}"><div></div><img src="assets/loop-mascot.svg" alt="Loop is finding subscriptions"></div>`+obTitle('A LITTLE CLARITY IS ON ITS WAY','Connecting the dots.','Turning your receipts into a clearer picture of your subscriptions.')+`<div class="ob-scan-stages" aria-live="polite">${['Finding receipts','Grouping subscriptions','Checking renewal details'].map((t,i)=>`<div class="${i<ob.scan?'done':i===ob.scan?'scanning':''}"><span>${i<ob.scan?'✓':'0'+(i+1)}</span>${t}</div>`).join('')}</div><div class="ob-bottom"><button class="primary" data-go="Your subscriptions" ${ob.scan<3?'disabled':''}>Review my subscriptions →</button></div>`;
 if(current==='Your subscriptions'){const total=obItems.reduce((a,v,i)=>a+(ob.selected.has(i)&&!v[7]?.trial?Number(v[2]):0),0).toFixed(2);body=obTop(4,'Connect inbox')+obTitle('YOUR FIRST LOOK','Small charges.<br><em>A clearer picture.</em>','We found 3 possible subscriptions. Review what you want to keep.')+`<div class="ob-total"><div><small>Estimated monthly cost</small><strong>USD ${total}</strong><span>${ob.selected.size} selected · paid plans only in total</span></div><div class="ob-donut"><span>${ob.selected.size}<small>selected</small></span></div></div>${obUpcoming()}<p class="ob-caption">SUBSCRIPTIONS FOUND <span>Review before saving</span></p><div class="ob-results">${obItems.map(([n,l,p,c,d,category,date,trial],i)=>`<label><input type="checkbox" data-ob-item="${i}" ${ob.selected.has(i)?'checked':''}><span class="ob-service service-${i}">${platformLogo(n)}</span><span><strong>${n}</strong><small>${trial?.trial?'Trial ends':'Renews'} ${d} · ${trial?.trial?'then $'+p+'/month':'estimated'}</small></span><b>${trial?.trial?'Free trial':'$'+p}</b></label>`).join('')}</div>${infoTooltip({"id": "estimates-info", "label": "How these estimates work", "paragraphs": ["Costs and renewal dates are estimated from your receipts. Older emails may refer to plans you\u2019ve already cancelled. Review each subscription before saving.", "Monthly cost is an estimate based on billing frequency and excludes active free trials. Trial rows show the price after trial. Upcoming events show expected charges in the next 7 days. Different currencies are shown separately, without conversion."], "className": "ob-estimates-info"})}<div class="ob-bottom"><button class="primary" data-ob="save" ${ob.selected.size?'':'disabled'}>Save ${ob.selected.size} subscriptions →</button>${btn('Nothing looks right? Add manually','Sign up','link')}</div>`;}
 if(current==='Save your finds'){const total=obItems.reduce((sum,item,i)=>sum+(ob.selected.has(i)&&!item[7]?.trial?Number(item[2]):0),0).toFixed(2);body=obTop(4,'Your subscriptions')+`<div class="ob-save-art"><img src="assets/renewless-mark.svg" alt="Renewless"><span>✓</span></div>`+obTitle('MAKE IT YOURS','Keep what<br><em>you found.</em>','Save your subscriptions and get reminded before they renew.')+`<div class="ob-save-summary"><span>${ob.selected.size} ${ob.selected.size===1?'subscription':'subscriptions'} selected</span><strong>USD ${total}<small> estimated/month</small></strong></div><p class="ob-save-free">Free to save. No payment required.</p><p class="ob-save-context">Create an account or sign in to keep your subscriptions.</p><div class="ob-bottom"><div class="ob-account">${['Google','Apple'].map(p=>`<button class="secondary social-button" data-ob="account">${socialIcon(p)}<span>Continue with ${p}</span></button>`).join('')}${btn('Continue with email','Sign up','link')}</div><div class="ob-save-legal"><button type="button" data-action="legal">Terms</button><span>·</span><button type="button" data-action="legal">Privacy</button></div></div>`;}
 if(current==='Ready to go'){
 const saved=obItems.filter((item,i)=>ob.selected.has(i));
 const totals=saved.reduce((out,item)=>{out[item[3]]=(out[item[3]]||0)+Number(item[2]);return out;},{});
 const next=saved.filter(item=>item[6]&&Date.parse(item[6])>=Date.UTC(2026,9,26)).sort((a,b)=>Date.parse(a[6])-Date.parse(b[6]))[0];
 body=obTop(5,'Save your finds')+`<div class="ob-ready-confetti" aria-hidden="true"><span class="ob-party-popper ob-party-left">🎉</span><span class="ob-party-popper ob-party-right">🎉</span>${Array.from({length:60},(_,i)=>`<i style="--x:${4+(i*37)%92}%;--drift:${(i%2?1:-1)*(20+(i*13)%75)}px;--delay:${.42+Math.floor(i/2)*.009}s;--travel:${440+(i*31)%190}px;--spread:${35+(i*23)%230}px;--turn:${180+(i*53)%540}deg;--color:${['#B9E58C','#E8EAED','#849B76','#E8BE78'][i%4]}"></i>`).join('')}</div><div class="ob-ready-celebration"><div class="ob-ready-halo"></div><div class="ob-ready-mascot"><img src="assets/loop-happy.svg" alt="Happy Loop celebrates your saved subscriptions"></div><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m6 12 4 4 8-9"/></svg></span></div>`+obTitle('A LITTLE LESS TO REMEMBER',`You’re all set,<br><em>${escape(ob.firstName||'Alex')}.</em>`,'Your subscriptions are together. Your next renewal is easier to keep track of.')+`<section class="ob-ready-summary"><div><strong>${saved.length}</strong><span>${saved.length===1?'subscription saved':'subscriptions saved'}</span></div><div><strong>${Object.entries(totals).map(([currency,total])=>`${escape(currency)} ${total.toFixed(2)}`).join(' · ')||'—'}</strong><span>Estimated monthly cost</span></div></section>${next?`<section class="ob-ready-next"><span class="ob-service">${platformLogo(next[0])}</span><div><small>NEXT ESTIMATED RENEWAL</small><strong>${escape(next[0])}</strong><span>${escape(next[4])} · ${escape(next[3])} ${escape(next[2])}</span></div></section>`:'<p class="ob-ready-empty">Add a renewal date to see what’s coming next.</p>'}<p class="ob-ready-reminder">Set reminders and stay ahead of your next renewal.</p><div class="ob-bottom">${btn('Go to my dashboard →','Home')}</div>`;
 }
 if(current==='Scan · no results')body=obTop(3,'Connect inbox')+`<div class="ob-empty-art"><img src="assets/loop-sad.svg?v=2" alt="Loop with a gently disappointed expression"><span aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg></span></div>`+obTitle('YOUR INBOX, CHECKED','No subscriptions<br><em>found this time.</em>','We didn’t find subscription receipts in this inbox from the last 12 months.')+`<section class="ob-empty-hint"><span class="ob-empty-hint-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z"/></svg></span><div><h3>Using another email for payments?</h3><p>Your receipts may be in a different inbox. Try the Gmail account you use for subscriptions.</p></div></section><p class="ob-empty-reassurance">You can still track any subscription by adding it yourself.</p><div class="ob-bottom">${btn('Try another Gmail account','Connect inbox')}${btn('Add a subscription manually','Sign up','secondary')}</div>`;
 if(current==='Scan · interrupted')body=obTop(3,'Connect inbox')+`<div class="ob-empty-art"><img src="assets/loop-sad.svg?v=2" alt="Loop with a gently disappointed expression"><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 9a13 13 0 0 1 16 0M7 12a8 8 0 0 1 10 0M10 15a3 3 0 0 1 4 0M12 19h.01M3 3l18 18"/></svg></span></div>`+obTitle('LET’S GET BACK ON TRACK','Your scan<br><em>was interrupted.</em>','We couldn’t finish checking your inbox. Reconnect and try again.')+`<section class="ob-empty-hint"><span class="ob-empty-hint-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/></svg></span><div><h3>A quick check before retrying</h3><p>Check your internet connection. If Google asks, allow read-only Gmail access so we can complete your scan.</p></div></section><p class="ob-empty-reassurance">You can also add subscriptions yourself and connect your inbox later.</p><div class="ob-bottom">${btn('Reconnect & try again','Connect inbox')}${btn('Add a subscription manually','Sign up','secondary')}</div>`;
 // Keep navigation and actions outside the independently scrolling content.
 const layout=document.createElement('template');layout.innerHTML=body;
 const top=layout.content.querySelector('.ob-top'),steps=layout.content.querySelector('.ob-steps'),footer=layout.content.querySelector('.ob-bottom');
 const headerHTML=(top?.outerHTML||'')+(steps?.outerHTML||'');top?.remove();steps?.remove();footer?.remove();
 const account=layout.content.querySelector('.ob-account');
 if(account&&footer){footer.prepend(account);const note=layout.content.querySelector(':scope > .note');if(note)footer.append(note);}
 const content=document.createElement('div');content.append(layout.content);
 return `<div class="ob-page"><header class="ob-fixed-top">${headerHTML}</header><div class="ob-scroll" tabindex="0" role="region" aria-label="${current} content">${content.innerHTML}</div>${footer?.outerHTML||''}</div>`;
}
function onboardingAfterRender(){document.querySelectorAll('.ob-ready-confetti').forEach(overlay=>{const phone=overlay.closest('.phone');if(phone)phone.append(overlay);});ob.timers.forEach(clearTimeout);ob.timers=[];if(current==='Splash')ob.timers.push(setTimeout(()=>go('Welcome'),2600));if(current==='Discovering'&&ob.scan<3)ob.timers.push(setTimeout(()=>{ob.scan++;render();},1100));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ob]');if(!b)return;if(b.dataset.ob==='save'&&ob.selected.size)go('Save your finds');if(b.dataset.ob==='account'){ob.account=true;ob.pending=false;go('Ready to go');}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-ob-item]'))return;const i=Number(e.target.dataset.obItem),scroll=e.target.closest('.ob-scroll'),offset=scroll?.scrollTop||0,expanded=scroll?.querySelector('details')?.open;e.target.checked?ob.selected.add(i):ob.selected.delete(i);render();const next=document.querySelector('#upgraded .ob-scroll');if(next){if(expanded)next.querySelector('details')?.setAttribute('open','');next.scrollTop=offset;}});

